import type { LinterResult } from "stylelint";

export enum Command {
  LINT = "lint",
  VERSION = "version",
  START = "start",
  STOP = "stop",
  RESTART = "restart",
  STATUS = "status",
  HELP = "help",
  __TEST__ = "__test__",
}

export interface LintArguments {
  files?: string[];
  stdin?: boolean;
  stdinFilename?: string;
  code?: string;
  codeFilename?: string;

